CREATE OR REPLACE FUNCTION public.fn_documentos_proteger_integridad()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  IF ROW(NEW.id, NEW.codigo, NEW.tipo_documental_id, NEW.registrado_por_id)
     IS DISTINCT FROM ROW(OLD.id, OLD.codigo, OLD.tipo_documental_id, OLD.registrado_por_id) THEN
    RAISE EXCEPTION 'Los identificadores y la autoria original son inmutables'
      USING ERRCODE = '23514';
  END IF;
  IF NOT OLD.activo AND (to_jsonb(NEW) - 'fecha_modificacion')
     IS DISTINCT FROM (to_jsonb(OLD) - 'fecha_modificacion') THEN
    RAISE EXCEPTION 'No se puede modificar un documento anulado' USING ERRCODE = '23514';
  END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.fn_movimientos_proteger_historial()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  IF ROW(NEW.id, NEW.documento_id, NEW.oficina_origen_id, NEW.usuario_origen_id,
         NEW.oficina_destino_id, NEW.usuario_destino_id, NEW.registrado_por_id, NEW.decidido_por_id)
     IS DISTINCT FROM
     ROW(OLD.id, OLD.documento_id, OLD.oficina_origen_id, OLD.usuario_origen_id,
         OLD.oficina_destino_id, OLD.usuario_destino_id, OLD.registrado_por_id, OLD.decidido_por_id) THEN
    RAISE EXCEPTION 'El origen y destino historicos son inmutables' USING ERRCODE = '23514';
  END IF;
  IF OLD.estado IN ('RECIBIDO','DEVUELTO','CANCELADO')
     AND (to_jsonb(NEW) - 'fecha_modificacion') IS DISTINCT FROM (to_jsonb(OLD) - 'fecha_modificacion') THEN
    RAISE EXCEPTION 'Movimiento cerrado inmutable' USING ERRCODE = '23514';
  END IF;
  IF NEW.estado IS DISTINCT FROM OLD.estado AND NOT (
       (OLD.estado = 'PENDIENTE_ENVIO' AND NEW.estado IN ('EN_TRASLADO','CANCELADO'))
    OR (OLD.estado = 'EN_TRASLADO' AND NEW.estado IN ('RECIBIDO','DEVOLUCION_PENDIENTE','CANCELADO'))
    OR (OLD.estado = 'DEVOLUCION_PENDIENTE' AND NEW.estado = 'DEVUELTO')
  ) THEN
    RAISE EXCEPTION 'Transicion de movimiento no permitida' USING ERRCODE = '23514';
  END IF;
  RETURN NEW;
END;
$function$
